def run(root, args, env=None):
    e = {k:v for k,v in os.environ.items() if not k.startswith("QUOTER_")}; e.update(env or {})
    p = subprocess.run([sys.executable,"-m","quoter",*args],cwd=root,env=e,capture_output=True,text=True)
    return p.returncode,p.stdout,p.stderr
opts = [[],["--currency","usd"],["--set","rounding=up","--set","round_step=0.05","--currency","GBP"],["--units","imperial","--debug"],
 ["--set","rate_card=2026","--set","pricing_date=2026-12-10","--set","surcharge_peak=3","--set","dim_divisor=4000"],
 ["--set","zone_overrides=CH=3,FR=5","--set","box_set=eco","--set","carriers=freight,ground","--set","round_step=10"],
 ["--set","zone_overrides=XX=3"],["--set","discount_tiers=1:3,x"],["--width","30","--set","label_format=long"],["--set","fuel_pct=20","--set","fx_margin=3","--currency","JPY","--set","rounding=half_even","--set","round_step=0.07"],
 ["--set","saturday_delivery=yes","--set","pricing_date=2026-12-22"],["--currency","xyz"],["--set","json_indent=0","--set","csv_delimiter=;"]]
