 ["quote","--from","DE-10115","--to","US-10001","--weight","30","--dims","110x50x40","--insure","900","--residential","--format","detail"],
 ["quote","--from","DE-10115","--to","DE-80331","--weight","3","--format","json"],["quote","--from","DE-10115","--to","GB-HS1 2AB","--weight","3","--format","csv"],
 ["quote","--from","DE-10115","--to","IT-90121","--weight","7","--format","label"],["carriers"],["zones","DE"],["zones","CH","--zone","3"],["settings"]]
